    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> ctx,
        ffi.Pointer<ffi.Void> memory,
        ffi.Size memory_len,
        ffi.Uint8 alignment,
        ffi.UintPtr ret_addr,
      )
    >
