  /// Size of this struct in bytes.
  @ffi.Size()
  external int size;

  /// Which step of the command this event reports.
  @ffi.UnsignedInt()
  external int kindAsInt;

  SemanticPromptKind get kind => SemanticPromptKind.fromValue(kindAsInt);
